fn replace_regex(_context: Context, s: &str, regex: &str, replacement: &str) -> FunctionResult {
  Ok(
    Regex::new(regex)
      .map_err(|err| err.to_string())?
      .replace_all(s, replacement)
      .to_string(),
  )
}

