  pub(crate) completions: Option<Shell>,
  #[arg(
    help = "Print justfile",
    help_heading = Self::HEADING,
    long,
  )]
  pub(crate) dump: bool,
  #[arg(
    help = "Edit justfile with editor given by $VISUAL or $EDITOR, falling back to `vim`",
    help_heading = Self::HEADING,
    long,
    short = 'e',
