    short = 'l',
    value_name = "MODULE",
  )]
  pub(crate) list: Option<Vec<String>>,
  #[arg(
    help = "Print man page",
    help_heading = Self::HEADING,
    long,
  )]
  pub(crate) man: bool,
  #[arg(
    help = "Execute <REQUEST>. For internal testing purposes only. May be changed or removed at \
            any time.",
