    paths.insert(root.clone(), root.clone());
    Analyzer::analyze(
      &asts,
      &Config::new().unwrap(),
      None,
      &[],
      &[],
      None,
      &mut HashMap::new(),
      &paths,
      false,
      &root,
    )
  }
